import {bank,topics,directions,cavities,membranes,regions,organs,systems,lessons,sources} from './data.js';
import {diagram} from './diagrams.js';
import {correct,normalize,empty,record,validateBackup} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>[...a].sort(()=>Math.random()-.5),KEY='anatomy-studio-v1';
let state=empty(),storageWarning='',session=null,learnTopic='direction',hideLabels=false,view='home',lastResults=[],game=null,strict=false,timed=false;
try{const s=localStorage.getItem(KEY);if(s)state=validateBackup(JSON.parse(s))}catch{storageWarning='Saved progress could not be read. Export any available backup before resetting; new work is kept in memory.'}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageWarning='Browser storage is unavailable. Export your progress before closing this page.'}};
const topicName=id=>topics.find(t=>t[0]===id)?.[1]||id;
const recall=()=>state.events.filter(e=>e.kind==='recall');
const accuracy=a=>a.length?`${Math.round(a.filter(e=>e.first&&!e.assisted).length/a.length*100)}%`:'Not started';
const due=()=>Object.entries(state.concepts).filter(([k,c])=>c.due<=Date.now());
const missed=()=>{let m=new Map();recall().forEach(e=>m.set(e.qid,e));return [...m.values()].filter(e=>!e.first||e.assisted).map(e=>bank.find(q=>q.id===e.qid))};
const link=(url,label='Check source')=>`<a class="source" href="${url}" target="_blank" rel="noopener">${label} ↗</a>`;
function layout(html){$('#main').innerHTML=(storageWarning?`<div role="alert" class="notice">${storageWarning}</div>`:'')+html;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${view}`));}
function home(){layout(`<div class="hero"><div><div class="eyebrow">A LITTLE PRACTICE, A CLEARER PICTURE</div><h1>Make anatomy<br><em>second nature.</em></h1><p>Build your vocabulary. Find your landmarks.<br>Get comfortable with the questions you’ll see in lab.</p><button class="primary" data-action="quick">Start a 10-question session <span>↗</span></button><div class="actions" style="margin-top:12px"><button class="textbutton" data-action="missed">Review missed questions</button><button class="textbutton" data-action="weak">Practice weak topics</button></div></div><div class="hero-art"><div class="figure-head"><span>YOUR BODY, MAPPED</span><span>FIG. 01</span></div>${diagram('cavities',null,true)}<div class="figure-caption">One connected body. A few landmarks at a time.</div></div></div><div class="summary"><div><span class="stat">${accuracy(recall())}</span><span class="subtle">First-attempt recall</span></div><div><span class="stat">${due().length}</span><span class="subtle">Concepts due for review</span></div><div><span class="stat">${state.sessions.length}</span><span class="subtle">Sessions completed</span></div></div><div class="sectionhead"><h2>Start with a topic</h2><span class="subtle">5 topics · ${bank.length} curated prompts</span></div><div class="grid">${topics.map((t,i)=>`<article class="card"><span class="number">0${i+1} / ${accuracy(recall().filter(e=>e.topic===t[0]))}</span><h3>${t[1]}</h3><p>${t[2]}</p><a href="#learn/${t[0]}">Explore topic ↗</a></article>`).join('')}<article class="card" style="background:var(--sage)"><span class="number">A DIFFERENT WAY TO PRACTICE</span><h3>A little play. A lot of recall.</h3><p>Place a label, follow a clue, or find your next landmark.</p><a href="#games">Find a study game ↗</a></article></div>${notes()}`)}
function notes(){return `<details><summary>Source notes & diagram limitations</summary><div class="notice">The request’s three worksheet images were not attached. This site uses the written scope; handwritten answers and worksheet-specific organ-region associations have not been reviewed. Those associations are excluded from scored questions.</div><p class="subtle">Accuracy notes: anatomical right belongs to the patient. The pancreas has digestive and endocrine roles; ovaries and testes have reproductive and endocrine roles. The male urethra also carries semen, though this course groups the urethra under urinary structures. Organs span multiple regions. A pleural or pericardial cavity is a potential space, whereas the mediastinum is a compartment. Kidneys are retroperitoneal; “abdominal” does not mean “inside the peritoneal cavity.”</p><p class="subtle">Original teaching schematics cover major body compartments, nine regions, serous layers, urinary structures, and female internal reproductive structures. Other organs, the mediastinum, and named organ-specific membranes use text recall until reliable individual identification views are added. Schematics simplify shape and scale; use course lab models for realistic identification. Screen-reader users can choose text-only practice.</p><p class="subtle">Checked against OpenStax, <i>Anatomy and Physiology 2e</i>, by Betts et al. (2022): ${Object.entries(sources).map(([k,v])=>link(v,k)).join(' · ')}. Original questions and diagrams; reference links provide the underlying anatomy.</p></details>`}
function learn(){let t=learnTopic;let rows=t==='direction'?directions.map(d=>[d[0],d[1],d[2].replace('___',d[0])]):t==='cavities'?cavities.map(c=>[c[0],c[1]]):t==='membranes'?membranes.map(m=>[m[0],m[1]]):t==='regions'?regions.map(r=>[r[0],r[1]]):organs.map(o=>[o[0],o[2],o[1].join(' + ')]);let ds=t==='regions'?['regions']:t==='membranes'?['membrane']:t==='organs'?['urinary','female']:['cavities'];layout(`<div class="eyebrow">LEARN / BUILD YOUR MENTAL MAP</div><h1>Get your bearings.</h1><div class="tabs">${topics.map(t=>`<button data-topic="${t[0]}" class="${learnTopic===t[0]?'selected':''}">${t[1]}</button>`).join('')}</div><div class="sectionhead"><h2>${topicName(t)}</h2><button data-action="topicpractice">Practice this topic ↗</button></div><p>${lessons[t]}</p><label><input type="checkbox" id="hide-labels" ${hideLabels?'checked':''}>Hide diagram labels for self-testing</label><div class="${ds.length>1?'twocol':''}" style="max-width:850px;margin:auto">${ds.map(d=>diagram(d,null,!hideLabels)).join('')}</div>${t==='direction'?'<p class="notice">Memory aid: proximal = proximity to attachment; distal = distant from attachment. Superficial and deep compare depth, not front and back.</p>':''}${t==='regions'?'<p class="notice">General verified examples: the stomach can span epigastric and left hypochondriac regions. The bladder projects into the hypogastric region; its size changes with filling. These are not exclusive organ boundaries.</p>':''}<div class="termcards" style="margin-top:25px">${rows.map(r=>`<article class="term"><h3>${r[0]}</h3><p>${r[1]}</p>${r[2]?`<p><b>${r[2]}</b></p>`:''}</article>`).join('')}</div>${notes()}`)}
function practice(){layout(`<div class="eyebrow">PRACTICE / RECALL BEFORE RECOGNITION</div><h1>A few questions.<br><em>A stronger memory.</em></h1><div class="twocol"><section class="panel"><h2>Make it your session</h2><label for="topic-select">Topic</label><select id="topic-select"><option value="all">Mixed · all five topics</option>${topics.map(t=>`<option value="${t[0]}">${t[1]}</option>`).join('')}</select><label for="mode-select">Mode</label><select id="mode-select"><option value="practice">Practice · feedback after each answer</option><option value="lab">Lab practical · grade at the end</option></select><label><input type="checkbox" id="strict" ${strict?'checked':''}>Strict spelling · exam preparation</label><label><input type="checkbox" id="timer" ${timed?'checked':''}>Show elapsed time (no countdown)</label><label><input type="checkbox" id="text-only">Text-only questions</label><button class="primary" data-action="configured">Start 10 questions ↗</button></section><section class="panel" style="background:var(--sage)"><span class="pill">WHAT TO EXPECT</span><h2 style="margin-top:25px">Find the word.<br>Find the structure.</h2><p>Type a word or short phrase. Mixed sessions include pinned diagrams when available.</p><p>Lab practicals use numbered stations, hidden labels, and no answer bank. Feedback arrives only when you submit the session.</p><p class="subtle">Capitalization, extra spaces, and harmless punctuation never matter. Only curated alternatives count as correct; similar-looking anatomy terms are not interchangeable.</p></section></div>`)}
function pick(pool,n){return shuffle(pool).slice(0,n)}
function start(pool=bank,name='Mixed practice',mode='practice',n=10,extra={}){if(!pool.length){layout(`<div class="empty"><h2>Nothing to review yet</h2><p>Complete a practice session to build a review list.</p><button data-action="quick">Start mixed practice</button></div>`);return}let questions=pick(pool,n);if(pool===bank&&n>=5){questions=topics.map(t=>pick(bank.filter(q=>q.topic===t[0]),1)[0]);questions.push(...pick(bank.filter(q=>!questions.includes(q)),n-questions.length));questions=shuffle(questions)}if(n>=10&&pool.some(q=>q.diagram)){let pins=pick(pool.filter(q=>q.diagram),Math.min(3,pool.filter(q=>q.diagram).length));questions=[...pins,...questions.filter(q=>!pins.includes(q))].slice(0,n);questions=shuffle(questions)}session={id:crypto.randomUUID(),name,mode,kind:'recall',questions,index:0,results:[],attempt:0,assisted:false,feedback:null,started:Date.now(),strict:strict||mode==='lab',timed,reviewConcepts:[...new Set(state.events.filter(e=>Date.now()-e.date<20*60*60*1000&&(!e.first||e.assisted||e.kind==='sort')).map(e=>e.concept))],...extra};session.reviewConcepts=[...new Set([...session.reviewConcepts,...state.events.filter(e=>Date.now()-e.date<20*60*60*1000&&(!e.first||e.assisted||e.kind==='sort')).map(e=>e.concept)])];view='practice';renderQuestion()}
function renderQuestion(){let s=session,q=s.questions[s.index];layout(`<section class="studybox"><div class="sectionhead"><span class="pill">${esc(s.name)}</span><button data-action="end">End session</button></div><div class="sectionhead"><span>${s.mode==='lab'?'Station':'Question'} ${s.index+1} of ${s.questions.length}</span><span class="subtle">${topicName(q.topic)} ${s.timed?'· <span id="elapsed">0:00</span>':''}</span></div><div class="meter"><span style="width:${s.index/s.questions.length*100}%"></span></div><div class="panel"><p class="prompt">${q.prompt}</p>${q.diagram?diagram(q.diagram,q.target,!!s.feedback&&s.mode!=='lab'):''}<form id="answer-form"><label for="answer">Your answer</label><input type="text" id="answer" name="answer" maxlength="160" spellcheck="${s.strict?'false':'true'}" autocomplete="off" autocorrect="off" autocapitalize="off" ${s.feedback?'disabled':''} required><div class="actions" style="margin-top:18px">${s.feedback?`<button type="button" class="primary" data-action="next">${s.index===s.questions.length-1?'Finish session':'Next question'} →</button>${!s.feedback.ok?'<button type="button" data-action="retry">Retry this item</button>':''}`:`<button class="primary" type="submit">${s.mode==='lab'?'Save answer & continue':'Check answer'} →</button>${s.mode!=='lab'?'<button type="button" data-action="hint">Show a hint</button><button type="button" class="textbutton" data-action="reveal">Reveal answer</button>':''}`}</div></form><div id="hint" aria-live="polite"></div>${s.feedback?`<div class="feedback ${s.feedback.ok?'success':'miss'}" role="status"><b>${s.feedback.ok?(s.attempt===1&&!s.assisted?'That’s right.':'Correct on review.'):'A useful one to revisit.'}</b><p>Expected: <strong>${q.answer}</strong></p><p>${q.explanation}</p>${link(q.source)}</div>`:''}</div>${s.mode==='lab'?'<p class="subtle">Your answers are saved for this session. No feedback is shown until submission.</p>':'<p class="subtle">First-attempt recall is tracked separately from hints and retries.</p>'}</section>`);if(!s.feedback)$('#answer')?.focus();}
function answer(value,reveal=false){const s=session,q=s.questions[s.index],ok=!reveal&&correct(q,value);s.attempt++;let r=s.results.find(r=>r.index===s.index);if(!r){r={qid:q.id,index:s.index,answer:value,first:ok&&!s.assisted&&!s.reviewConcepts?.includes(q.concept),assisted:s.assisted||reveal||!!s.reviewConcepts?.includes(q.concept),eventual:ok};s.results.push(r)}else {r.eventual=r.eventual||ok;r.assisted=r.assisted||s.assisted||reveal;}if(s.mode==='lab'){next();return}if(!ok&&!s.trail&&!s.reviewConcepts.includes(q.concept))s.reviewConcepts.push(q.concept);if(s.trail&&!ok&&!s.trailReturns.includes(q.concept)){s.trailReturns.push(q.concept);s.reviewConcepts.push(q.concept);const alternate=bank.find(x=>x.topic==='direction'&&x.prompt.includes('___')&&x.concept===q.concept&&x.id!==q.id&&!s.questions.slice(s.index+1).includes(x));if(alternate)s.questions.push(alternate)}s.feedback={ok};renderQuestion();}
function next(){session.index++;if(session.index>=session.questions.length){if(session.mode==='lab'){layout(`<section class="studybox panel"><h2>Ready to submit your practical?</h2><p>You have answered ${session.results.length} stations. Submit to reveal your results.</p><button class="primary" data-action="submitlab">Submit lab practical</button></section>`)}else finish();return}session.attempt=0;session.assisted=false;session.feedback=null;renderQuestion()}
function finish(){let s=session;record(state,s);save();lastResults=s.results.map(r=>({...r}));session=null;layout(`<section class="studybox"><span class="pill">SESSION COMPLETE</span><h1>A little clearer.</h1><div class="summary"><div><span class="stat">${s.results.filter(r=>r.first&&!r.assisted).length}/${s.results.length}</span><span class="subtle">Independent first attempts</span></div><div><span class="stat">${s.results.filter(r=>r.eventual).length}</span><span class="subtle">Eventually correct</span></div><div><span class="stat">${s.results.filter(r=>r.assisted).length}</span><span class="subtle">Assisted items</span></div></div><div class="actions"><button class="primary" data-action="retrymissed">Retry missed items</button><a class="button" href="#progress">See progress</a><button data-action="quick">New session</button></div>${s.results.map(r=>{let q=bank.find(q=>q.id===r.qid);return `<article class="panel"><span class="pill">${r.first&&!r.assisted?'Independent recall':r.eventual?'Correct after review':'Revisit'}</span><h3 style="margin-top:15px">${q.prompt}</h3>${q.diagram?diagram(q.diagram,q.target,true):''}<p>Your answer: ${esc(r.answer||'Revealed')}<br>Expected: <b>${q.answer}</b></p><p>${q.explanation}</p>${link(q.source)}</article>`}).join('')}</section>`)}
function games(){layout(`<div class="eyebrow">GAMES / CHANGE YOUR PACE</div><h1>Play your way<br><em>to better recall.</em></h1><p>Short rounds. Gentle feedback. No lives to lose.</p><div class="grid">${[['pinpoint','01','Pinpoint','A pin, a structure, and your own words. Identify six landmarks without a label bank.'],['regions','02','Region Builder','Place all nine regions, then put the labels away for typed recall.'],['trail','03','Term Trail','Follow six directional clues. A missed concept returns in a new example.'],['sort','04','System Sort','Connect organs to every course system they belong to, then recall them from memory.']].map(g=>`<article class="card"><span class="number">${g[1]} / 3–6 MINUTES</span><h2>${g[2]}</h2><p>${g[3]}</p><button data-game="${g[0]}" class="primary">Play ${g[2]} ↗</button></article>`).join('')}</div>`)}
function regionGame(){game={type:'regions',labels:shuffle(regions.map((r,i)=>i)),placed:Array(9).fill(null),selected:null,checked:false};renderRegions()}
function renderRegions(){layout(`<section class="studybox"><span class="pill">REGION BUILDER / PLACE THE MAP</span><h1>Nine places.<br><em>One mental map.</em></h1><p>Select a label, then select its square. Select a filled square with no label chosen to remove it.</p><div class="figure-head"><span>PATIENT’S RIGHT</span><span>ANTERIOR VIEW</span><span>PATIENT’S LEFT</span></div><div class="region-grid">${game.placed.map((r,i)=>`<button data-cell="${i}" class="${r!==null?'filled':''}" aria-label="${['Upper','Middle','Lower'][Math.floor(i/3)]} row, ${['patient right','center','patient left'][i%3]}: ${r===null?'empty':regions[r][0]}">${r===null?'＋':regions[r][0]}</button>`).join('')}</div><div class="region-labels">${game.labels.filter(i=>!game.placed.includes(i)).map(i=>`<button class="${game.selected===i?'selected':''}" data-region="${i}" aria-pressed="${game.selected===i}">${regions[i][0]}</button>`).join('')}</div><div class="actions" style="margin-top:20px"><button class="primary" data-action="checkregions">Check my map</button><a href="#games" class="button">Leave game</a></div><div id="game-feedback" aria-live="polite"></div></section>`)}
function checkRegions(){if(game.placed.includes(null)){$('#game-feedback').innerHTML='<p class="notice">Place all nine labels first.</p>';return}let ok=game.placed.every((v,i)=>v===i);if(!game.checked){record(state,{id:crypto.randomUUID(),name:'Region Builder · placement',kind:'sort',results:game.placed.map((v,i)=>({qid:bank.find(q=>q.diagram==='regions'&&q.target===i).id,answer:regions[v][0],first:v===i,eventual:v===i,assisted:false}))});save();game.checked=true}$('#game-feedback').innerHTML=ok?'<div class="feedback success"><b>Your map is in place.</b><p>Now try three typed questions with no label bank.</p><button class="primary" data-action="regionrecall">Continue to recall →</button></div>':`<div class="feedback miss"><b>${game.placed.filter((v,i)=>v===i).length} of 9 are in place.</b><p>Correct order, from your left: ${regions.map(r=>r[0]).join(' · ')}. Adjust your map, then check again.</p></div>`;}
function sortGame(){game={type:'sort',items:shuffle([organs.find(o=>o[0]==='pancreas'),organs.find(o=>o[0]==='ovaries'),organs.find(o=>o[0]==='testes'),...pick(organs.filter(o=>o[1].length===1),2)]),index:0,results:[],feedback:null};renderSort()}
function renderSort(){let o=game.items[game.index];layout(`<section class="studybox panel"><span class="pill">SYSTEM SORT / ${game.index+1} OF ${game.items.length}</span><h1>${o[0]}</h1><p>Select every system listed for this organ in the course scope.</p><form id="sort-form"><div class="choices">${systems.map(s=>`<label><input type="checkbox" name="system" value="${s}" ${game.feedback?'disabled':''}>${s}</label>`).join('')}</div><div class="actions" style="margin-top:20px">${game.feedback?'<button type="button" class="primary" data-action="sortnext">Continue →</button>':'<button class="primary">Check systems</button>'}<a class="button" href="#games">Leave game</a></div></form>${game.feedback?`<div class="feedback ${game.feedback.ok?'success':'miss'}" role="status"><b>${game.feedback.ok?'That’s the connection.':'Here’s the connection.'}</b><p>${o[0]} → ${o[1].join(' + ')}</p><p>${o[2]}</p></div>`:''}</section>`)}
function progress(){const events=recall(),sorts=state.events.filter(e=>e.kind==='sort'),mastered=Object.values(state.concepts).filter(c=>c.streak>=3).length;const confusions={};events.filter(e=>!e.first&&e.answer).forEach(e=>{let q=bank.find(q=>q.id===e.qid),k=`${e.answer} → ${q.answer}`;confusions[k]=(confusions[k]||0)+1});layout(`<div class="eyebrow">PROGRESS / YOUR OWN PACE</div><h1>See what’s<br><em>staying with you.</em></h1><div class="summary"><div><span class="stat">${accuracy(events)}</span><span class="subtle">Unassisted first-attempt recall</span></div><div><span class="stat">${mastered}</span><span class="subtle">Concepts holding steady</span></div><div><span class="stat">${due().length}</span><span class="subtle">Due for another review</span></div></div><div class="actions"><button class="primary" data-action="due">Review due concepts</button><button data-action="missed">Review missed questions</button></div><div class="sectionhead"><h2>Topic by topic</h2></div><div class="grid">${topics.map(t=>{let es=events.filter(e=>e.topic===t[0]);return `<article class="card"><h3>${t[1]}</h3><span class="stat">${accuracy(es)}</span><p>${es.length?`${es.length} recall attempts · ${es.filter(e=>e.eventual).length} eventually correct`:'A fresh place to begin.'}</p></article>`}).join('')}<article class="card"><h3>Matching & sorting</h3><span class="stat">${accuracy(sorts)}</span><p>${sorts.length} placements. Tracked separately from typed recall.</p></article></div><div class="twocol"><section class="panel"><h2>Words to untangle</h2>${Object.keys(confusions).length?Object.entries(confusions).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,n])=>`<p>${esc(k)} <span class="subtle">(${n})</span></p>`).join(''):'<p>Your common confusions will appear after you practice.</p>'}</section><section class="panel"><h2>How review works</h2><p>Missed or assisted concepts return in 10 minutes. Independent correct recall spaces reviews to 1, 3, 7, 14, then 30 days.</p><p>“Holding steady” means independent recall on at least three study days. Repeating a question today does not count as a new study day.</p><p class="subtle">A first attempt with a hint or a prior reveal is assisted. Correcting it is progress, but it is not independent mastery.</p></section></div><section class="panel"><h2>Session history</h2>${state.sessions.length?`<div style="overflow-x:auto"><table class="history"><thead><tr><th>Date</th><th>Session</th><th>First attempt</th></tr></thead><tbody>${state.sessions.slice(-30).reverse().map(s=>`<tr><td>${new Date(s.date).toLocaleDateString()}</td><td>${esc(s.name)}</td><td>${s.correct}/${s.count}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Recent recall: ${accuracy(events.slice(-20))} · Previous 20 attempts: ${accuracy(events.slice(-40,-20))}. These windows may contain different topics.</p>`:'<div class="empty">No sessions yet. Your first one starts the story.</div>'}</section><section class="panel"><h2>Keep your progress safe</h2><p>Progress is saved in this browser. It does not automatically sync across devices and can be lost when browser data is cleared. Import replaces current progress.</p><div class="actions"><button data-action="export">Export progress</button><button data-action="import">Import backup</button><input class="hidden" type="file" id="import-file" accept="application/json,.json"><button data-action="reset">Reset progress</button></div><div id="backup-message" role="status"></div></section>${notes()}`)}
function confirmDialog(title,body,action){let d=document.createElement('dialog');d.innerHTML=`<h2>${title}</h2><p>${body}</p><div class="actions"><button id="cancel-dialog">Cancel</button><button class="primary" id="confirm-dialog">Confirm</button></div>`;document.body.append(d);d.showModal();d.querySelector('#cancel-dialog').onclick=()=>{d.close();d.remove()};d.querySelector('#confirm-dialog').onclick=()=>{d.close();d.remove();action()};d.addEventListener('cancel',()=>d.remove());}
function route(){if(location.hash==='#main')return;session=null;game=null;let [v,t]=location.hash.slice(1).split('/');view=['learn','practice','games','progress'].includes(v)?v:'home';if(t&&topics.some(x=>x[0]===t))learnTopic=t;({home,learn,practice,games,progress}[view])();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-topic],[data-game],[data-region],[data-cell]');if(!b)return;if(b.dataset.topic){learnTopic=b.dataset.topic;learn();return}if(b.dataset.game){let g=b.dataset.game;if(g==='pinpoint')start(bank.filter(q=>q.diagram),'Pinpoint','practice',6);if(g==='trail')start(bank.filter(q=>q.topic==='direction'&&q.prompt.includes('___')),'Term Trail','practice',6,{trail:true,trailReturns:[]});if(g==='regions')regionGame();if(g==='sort')sortGame();return}if(b.dataset.region!==undefined){game.selected=+b.dataset.region;renderRegions();document.querySelector('[data-cell]')?.focus();return}if(b.dataset.cell!==undefined){let i=+b.dataset.cell;if(game.selected!==null){game.placed[i]=game.selected;game.selected=null}else game.placed[i]=null;renderRegions();return}
const a=b.dataset.action;if(a==='quick')start();if(a==='configured'){strict=$('#strict').checked;timed=$('#timer').checked;let topic=$('#topic-select').value,mode=$('#mode-select').value;let pool=bank.filter(q=>(topic==='all'||q.topic===topic)&&(!$('#text-only').checked||!q.diagram));start(pool,mode==='lab'?'Lab practical':topic==='all'?'Mixed practice':topicName(topic),mode)}if(a==='missed')start(missed(),'Missed question review');if(a==='weak'){let started=topics.map(t=>({id:t[0],es:recall().filter(e=>e.topic===t[0])})).filter(t=>t.es.length);let weak=started.sort((a,b)=>a.es.filter(e=>e.first&&!e.assisted).length/a.es.length-b.es.filter(e=>e.first&&!e.assisted).length/b.es.length)[0];start(weak?bank.filter(q=>q.topic===weak.id):bank,weak?'Focus: '+topicName(weak.id):'Discover your starting point')}if(a==='due'){let keys=due().map(x=>x[0]);start(bank.filter(q=>keys.includes(`${q.topic}:${q.concept}`)),'Spaced review')}if(a==='topicpractice')start(bank.filter(q=>q.topic===learnTopic),topicName(learnTopic));if(a==='hint'){session.assisted=true;$('#hint').innerHTML='<p class="notice">First letter: <b>'+session.questions[session.index].answer[0].toUpperCase()+'</b>. This answer will be marked assisted.</p>'}if(a==='reveal'){session.assisted=true;answer('',true)}if(a==='retry'){session.assisted=true;session.feedback=null;renderQuestion()}if(a==='next')next();if(a==='submitlab')finish();if(a==='retrymissed'){let ids=lastResults.filter(r=>!r.first||r.assisted).map(r=>r.qid);start(bank.filter(q=>ids.includes(q.id)),'Retry missed items','practice',10,{reviewConcepts:bank.filter(q=>ids.includes(q.id)).map(q=>q.concept)})}if(a==='end')confirmDialog('End this session?','This unfinished session will not be included in your progress.',()=>{session=null;practice()});if(a==='checkregions')checkRegions();if(a==='regionrecall')start(bank.filter(q=>q.topic==='regions'&&!q.diagram),'Region Builder · typed recall','practice',3,{reviewConcepts:regions.map(r=>r[0])});if(a==='sortnext'){game.index++;if(game.index<game.items.length){game.feedback=null;renderSort()}else{record(state,{id:crypto.randomUUID(),name:'System Sort · matching',kind:'sort',results:game.results});save();let names=game.items.map(o=>o[0]);start(bank.filter(q=>q.topic==='organs'&&names.includes(q.answer)),'System Sort · typed recall','practice',3,{reviewConcepts:names})}}if(a==='import')$('#import-file').click();if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const l=document.createElement('a');l.href=url;l.download='anatomy-study-progress.json';l.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#backup-message').textContent='Backup exported.'}if(a==='reset')confirmDialog('Reset all progress?','This removes your study history and review schedule from this browser. Export a backup first if you want to keep it.',()=>{state=empty();save();progress()});});
document.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();answer($('#answer').value)}if(e.target.id==='sort-form'){e.preventDefault();let o=game.items[game.index],chosen=[...document.querySelectorAll('[name=system]:checked')].map(x=>x.value),ok=chosen.length===o[1].length&&o[1].every(s=>chosen.includes(s));game.results.push({qid:bank.find(q=>q.topic==='organs'&&q.concept===o[0]&&q.prompt.startsWith('Name the course system')||q.topic==='organs'&&q.concept===o[0]&&q.prompt.startsWith('Name one of')).id,answer:chosen.join(', '),first:ok,eventual:ok,assisted:false});game.feedback={ok};renderSort()}});
document.addEventListener('change',async e=>{if(e.target.id==='hide-labels'){hideLabels=e.target.checked;learn()}if(e.target.id==='import-file'){try{let file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('This backup is too large.');const data=validateBackup(JSON.parse(await file.text()));confirmDialog('Replace current progress?',`Import ${data.sessions.length} sessions from this backup?`,()=>{state=data;save();progress();$('#backup-message').textContent='Progress imported successfully.'})}catch(err){$('#backup-message').textContent=err.message}e.target.value=''}});
setInterval(()=>{if(session?.timed&&$('#elapsed')){let n=Math.floor((Date.now()-session.started)/1000);$('#elapsed').textContent=`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}},1000);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_study_progress',description:'Read this browser’s study summary without changing progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({sessions:state.sessions.length,firstAttemptAccuracy:accuracy(recall()),dueConcepts:due().length})});document.modelContext.registerTool({name:'start_study_session',description:'Start a 10-question practice session. Does not answer or complete questions.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:['all',...topics.map(t=>t[0])]}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['all',...topics.map(t=>t[0])].includes(input.topic))throw Error('Unknown topic');if(session)throw Error('A session is already active');start(input.topic==='all'?bank:bank.filter(q=>q.topic===input.topic),input.topic==='all'?'Mixed practice':topicName(input.topic));return {started:true,questions:session.questions.length}}})}catch{}}
route();
// Same-route navigation must also leave an activity opened within that route.
document.querySelector('nav').addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.hash===location.hash){e.preventDefault();route();}});
